import { productBodyTextStyle } from "../components/productTypography";
import ProductSectionTitle from "../components/ProductSectionTitle";
import NewProductForm from "../components/NewProductForm";
import { Text } from "../i18n/LocalizedText";
import ProductCostHistory from "../components/ProductCostHistory";
import ProductSalesHistoryScreen from "./ProductSalesHistoryScreen";
import ProductBrandField from "../components/ProductBrandField";
import * as ImagePicker from "expo-image-picker";
import * as ImageManipulator from "expo-image-manipulator";
import { Ionicons } from "@expo/vector-icons";import { router, useLocalSearchParams } from "expo-router";
import { useCallback, useEffect, useMemo, useState } from "react";
import { ActivityIndicator, Alert, Text as NativeText, Image, Modal, Platform, Pressable, ScrollView, StyleSheet, TextInput, useWindowDimensions, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
