type Variant = { id: string; variantValuesJson: string; sku: string; barcode: string; imageUrl: string | null; note: string | null; priceOverride: number | null; isDefault: boolean; avgLandedCost?: number; stock?: number; rowVer?: number[]; offerRegularPrice?: number | null; activeOfferPercent?: number; activeOfferName?: string | null };
type ProductImage = { id: string; imageUrl: string; sortOrder: number };
type MarketplaceSection = "STYLE" | "FEATURES_SPECS" | "ITEM_DETAILS";
type MarketplaceDetail = { id: string; section: MarketplaceSection; label: string; value: string; sortOrder: number };
type MarketplaceTemplate = { section: MarketplaceSection; label: string; valuePlaceholder: string | null; sortOrder: number };
type Product = { id: string; categoryId: string; name: string; sku: string; imageUrl: string | null; description: string | null; defectNotes: string | null; unitCode: string; sellingPrice: number; marketPrice: number | null; marketplacePrice: number | null; packagingCostPerUnit?: number; lowStockThreshold: number; attributesJson: string | null; note: string | null; status: string; categoryName: string; variants: Variant[]; rowVer?: number[]; showOnMarketplace?: boolean; youtubeUrl: string | null; marketplaceDetails: MarketplaceDetail[]; images: ProductImage[]; warrantyDurationValue: number | null; warrantyDurationUnit: string | null; wholesaleMinQty: number | null; wholesaleUnitPrice: number | null; wholesaleNote: string | null };
type Adjustment = { id: string; reason: string; qty: number; note: string | null; userName: string; createdAt: string };
type CategoryField = { id: string; name: string; fieldType: string; optionsJson?: string | null; isVariant: boolean };
type Tab = "salesHistory" | "costHistory" | "info" | "variants" | "prices" | "stock" | "marketplace";
const media = (value?: string | null) => !value ? null : /^https?:\/\//i.test(value) ? value : `${MEDIA_URL}${value}`;
const MAX_PRODUCT_IMAGES = 10;
const confirmPriceAction = (title: string, message: string, buttons: NonNullable<Parameters<typeof Alert.alert>[2]>) => {
  if (Platform.OS === "web") {
    if (window.confirm(`${title}\n\n${message}`)) buttons.find(button => button.style === "destructive")?.onPress?.();
    return;
  }
  Alert.alert(title, message, buttons);
};
const money = (value?: number | null) => `৳${Number(value ?? 0).toLocaleString("en-BD", { maximumFractionDigits: 2 })}`;
const variantName = (variant: Variant) => { try { const values = Object.values(JSON.parse(variant.variantValuesJson || "{}") as Record<string, string>).filter(Boolean); return values.length ? values.join(" / ") : variant.sku; } catch { return variant.sku; } };
type ReusableDiscount = { id: string; name: string; percent: number; reason: string | null; startDate: string; endDate: string | null; isArchived: boolean };
type ActiveDiscountAssignment = { discountId: string; discountName: string; variantId: string };

export default function ProductDetailScreen() {
  const { t } = useLanguage();
  const auth = useAuth(); const { id } = useLocalSearchParams<{ id: string }>();
  const role = auth.session?.user.role ?? "STAFF"; const isOwner = role === "OWNER"; const canAdjust = role === "OWNER" || role === "MANAGER";
  const [product, setProduct] = useState<Product | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [tab, setTab] = useState<Tab>("info"); const [edit, setEdit] = useState(false); const [saving, setSaving] = useState(false); const [selectedVariantId, setSelectedVariantId] = useState<string | null>(null);
  const load = useCallback(async () => { if (!id) return; setLoading(true); setError(""); try { setProduct(await auth.api<Product>(`/products/${id}`)); } catch (e) { setError((e as Error).message); } finally { setLoading(false); } }, [id, auth.session?.businessId, auth.session?.branchId]);
  useEffect(() => { void load(); }, [load]);
  const archive = () => confirmPriceAction("Delete product", "This removes the product from active lists while preserving its order and purchase history.", [{ text: "Cancel", style: "cancel" }, { text: "Delete", style: "destructive", onPress: async () => { try { await auth.api(`/products/${id}/archive`, { method: "PATCH" }); router.replace("/products"); } catch (e) { setError((e as Error).message); } } }]);
  const totalStock = useMemo(() => product?.variants.reduce((sum, variant) => sum + Number(variant.stock ?? 0), 0) ?? 0, [product]);
  // Temporarily hidden by request. Keep the Variants screen implemented and reachable from Info actions.
  const tabs: { key: Tab; label: string }[] = [{ key: "info", label: "Info" }, ...(canAdjust ? [{ key: "prices" as Tab, label: "Price Settings" }] : []), ...(canAdjust ? [{ key: "stock" as Tab, label: "Adjust Stock" }] : []), ...(isOwner ? [{ key: "marketplace" as Tab, label: "Marketplace" }] : []), ...(canAdjust ? [{ key: "costHistory" as Tab, label: t("productCostHistory.title") }] : [])];
  if (loading && !product) return <View style={s.state}><ActivityIndicator color={colors.primary} size="large" /><Text style={s.muted}>Loading product…</Text></View>;
  if (!product) return <View style={s.state}><Ionicons name="warning-outline" size={38} color={colors.danger} /><Text style={s.error}>{error || "Product not found."}</Text><Pressable onPress={() => void load()} style={s.primary}><Text style={s.primaryText}>Try again</Text></Pressable></View>;
  return <View style={s.root}>
    <View style={s.header}><View style={s.titleRow}><Pressable onPress={() => router.replace("/products")} hitSlop={8}><Ionicons name="chevron-back" size={23} color={colors.secondary} /></Pressable><View style={s.titleCopy}><Text numberOfLines={1} style={s.title}>{product.name}</Text><Text style={s.subtitle}>{product.sku} · {product.categoryName}</Text></View>{isOwner && product.status === "ACTIVE" && <Pressable onPress={archive} style={s.deleteButton}><Text style={s.deleteText}>Delete</Text></Pressable>}</View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.tabs}>{tabs.map(item => <Pressable key={item.key} accessibilityRole="tab" accessibilityState={{ selected: tab === item.key }} onPress={() => setTab(item.key)} style={[s.tab, tab === item.key && s.activeTab]}><Text style={[s.tabText, tab === item.key && s.activeTabText]}>{item.key === "costHistory" ? <NativeText>{t("productCostHistory.title")}</NativeText> : item.label}</Text></Pressable>)}</ScrollView></View>
    {tab === "salesHistory" && canAdjust ? <ProductSalesHistoryScreen key={product.id} productId={product.id} productName={product.name} /> : <ScrollView contentContainerStyle={s.content}>{!!error && <Text style={s.errorBox}>{error}</Text>}{tab === "info" && <Info product={product} totalStock={totalStock} owner={isOwner} canAdjust={canAdjust} auth={auth} reload={load} edit={() => setEdit(true)} go={setTab} />}{tab === "variants" && <Variants product={product} auth={auth} owner={isOwner} canAdjust={canAdjust} reload={load} price={variant => { setSelectedVariantId(variant.id); setTab("prices"); }} stock={variant => { setSelectedVariantId(variant.id); setTab("stock"); }} />}{tab === "prices" && canAdjust && <Prices product={product} auth={auth} reload={load} initialVariantId={selectedVariantId} manageCost={() => setTab("costHistory")} />}{tab === "costHistory" && canAdjust && <ProductCostHistory productId={product.id} variants={product.variants} reload={load} />}{tab === "stock" && canAdjust && <Stock product={product} auth={auth} reload={load} initialVariantId={selectedVariantId} />}{tab === "marketplace" && isOwner && <Marketplace product={product} auth={auth} reload={load} />}</ScrollView>}
    <EditModal visible={edit} product={product} saving={saving} close={() => setEdit(false)} save={async payload => { setSaving(true); setError(""); try { const updated = await auth.api<Product>(`/products/${id}`, { method: "PUT", body: JSON.stringify(payload) }); setProduct(updated); setEdit(false); } catch (e) { setError((e as Error).message); throw e; } finally { setSaving(false); } }} />
  </View>;
}

type ProductOrder = { id: string; orderNo: string; createdAt: string; totalAmount: number; paymentStatus: string; items: { productId: string; qty: number }[] };
function Info({ product, totalStock, owner, canAdjust, auth, reload, edit, go }: { product: Product; totalStock: number; owner: boolean; canAdjust: boolean; auth: ReturnType<typeof useAuth>; reload: () => Promise<void>; edit: () => void; go: (tab: Tab) => void }) {
  const { t, lang } = useLanguage();
  const bn = lang === "bn";
  const needsPrice = product.variants.some(variant => (variant.priceOverride ?? product.sellingPrice) <= 0);
  const source = media(product.imageUrl); const out = totalStock <= 0; const low = !out && totalStock <= product.lowStockThreshold; const warranty = product.warrantyDurationValue ? `${product.warrantyDurationValue} ${product.warrantyDurationUnit ?? ""}` : "No warranty";
  const [viewer, setViewer] = useState<string | null>(null); const [busy, setBusy] = useState(""); const [orders, setOrders] = useState<ProductOrder[]>([]);
  useEffect(() => { auth.api<ProductOrder[]>(`/products/${product.id}/orders`).then(setOrders).catch(() => setOrders([])); }, [product.id]);
  const payload = (imageUrl: string | null) => ({ categoryId: product.categoryId, name: product.name, imageUrl, description: product.description, defectNotes: product.defectNotes, unitCode: product.unitCode, sellingPrice: product.sellingPrice, marketPrice: product.marketPrice, packagingCostPerUnit: product.packagingCostPerUnit ?? 0, lowStockThreshold: product.lowStockThreshold, attributesJson: product.attributesJson, note: product.note, status: product.status, rowVer: product.rowVer, warrantyDurationValue: product.warrantyDurationValue, warrantyDurationUnit: product.warrantyDurationUnit, wholesaleMinQty: product.wholesaleMinQty, wholesaleUnitPrice: product.wholesaleUnitPrice, wholesaleNote: product.wholesaleNote });
  const [uploadPercent, setUploadPercent] = useState<number | null>(null);
  const upload = async (multiple = false) => {
    const remainingSlots = Math.max(1, MAX_PRODUCT_IMAGES - product.images.length - (product.imageUrl ? 1 : 0));
    const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ["images"], allowsMultipleSelection: multiple, allowsEditing: !multiple, selectionLimit: multiple ? remainingSlots : 1, quality: .9, aspect: [1, 1] });
    if (result.canceled) return [] as string[];
    if (!multiple) setUploadPercent(0);
    const urls: string[] = [];
    for (const asset of result.assets) {
      const cropped = await ImageManipulator.manipulateAsync(asset.uri, [], { compress: .9, format: ImageManipulator.SaveFormat.JPEG });
      const output = cropped.width > 400
        ? await ImageManipulator.manipulateAsync(cropped.uri, [{ resize: { width: 400 } }], { compress: .76, format: ImageManipulator.SaveFormat.JPEG })
        : await ImageManipulator.manipulateAsync(cropped.uri, [], { compress: .76, format: ImageManipulator.SaveFormat.JPEG });
      const form = new FormData();
      if (Platform.OS === "web") {
        const blob = await (await fetch(output.uri)).blob();
        form.append("file", new File([blob], "product.jpg", { type: "image/jpeg" }));
      } else {
        form.append("file", { uri: output.uri, name: "product.jpg", type: "image/jpeg" } as never);
      }
      let uploadedUrl: string;
      if (multiple) {
      const response = await fetch(`${MEDIA_URL}/api/v1/media/upload`, { method: "POST", headers: { Authorization: `Bearer ${auth.session?.accessToken || ""}`, ...(auth.session?.businessId ? { "X-Business-Id": auth.session.businessId } : {}) }, body: form });
      const body = await response.json();
      if (!response.ok || !body.url) throw new Error(body.message || "Image upload failed.");
        uploadedUrl = body.url;
      } else {
        uploadedUrl = await new Promise<string>((resolve, reject) => {
          const request = new XMLHttpRequest();
          request.open("POST", `${MEDIA_URL}/api/v1/media/upload`);
          request.setRequestHeader("Authorization", `Bearer ${auth.session?.accessToken || ""}`);
          if (auth.session?.businessId) request.setRequestHeader("X-Business-Id", auth.session.businessId);
          request.timeout = 120000;
          request.upload.onprogress = event => {
            if (event.lengthComputable) setUploadPercent(Math.min(100, Math.round(event.loaded / event.total * 100)));
          };
          request.onload = () => {
            try {
              const body = JSON.parse(request.responseText);
              if (request.status < 200 || request.status >= 300 || !body.url) throw new Error(body.message || "Image upload failed.");
              setUploadPercent(100);
              resolve(body.url);
            } catch (error) { reject(error); }
          };
          request.onerror = () => reject(new Error("Image upload failed."));
          request.ontimeout = () => reject(new Error("Image upload timed out. Please try again."));
          request.onabort = () => reject(new Error("Image upload canceled."));
          request.send(form);
        });
      }
      urls.push(uploadedUrl);
    }
    return urls;
  };
  const changeMain = async () => { setBusy("main"); try { const [url] = await upload(); if (!url) return; await auth.api(`/products/${product.id}`, { method: "PUT", body: JSON.stringify(payload(url)) }); await reload(); } catch (e) { Alert.alert("Image", (e as Error).message); } finally { setBusy(""); setUploadPercent(null); } };
  const [imageDelete, setImageDelete] = useState<{ id: string | null; url: string; detached?: boolean } | null>(null);
  const [imageDeleteError, setImageDeleteError] = useState("");
  const removeMain = () => { if (product.imageUrl) { setImageDeleteError(""); setImageDelete({ id: null, url: product.imageUrl }); } };
  const confirmImageDelete = async () => {
    if (!imageDelete || busy) return;
    setBusy(imageDelete.id ?? "main"); setImageDeleteError("");
    try {
      if (!imageDelete.detached) {
        if (imageDelete.id) await auth.api(`/products/${product.id}/images/${imageDelete.id}`, { method: "DELETE" });
        else await auth.api(`/products/${product.id}`, { method: "PUT", body: JSON.stringify(payload(null)) });
        setImageDelete({ ...imageDelete, detached: true });
      }
      // Shared catalog and external images are not owned upload files.
      const prefix = `/uploads/${auth.session?.businessId}/`;
      if (imageDelete.url.startsWith(prefix)) {
        const response = await fetch(`${MEDIA_URL}/api/v1/media/product-image?url=${encodeURIComponent(imageDelete.url)}`, {
          method: "DELETE", headers: { Authorization: `Bearer ${auth.session?.accessToken || ""}`, "X-Business-Id": auth.session?.businessId ?? "" },
        });
        if (!response.ok) {
          const body = await response.json().catch(() => null);
          throw new Error(body?.message || t("productInfo.imageDeleteFailed"));
        }
      }
      await reload(); setImageDelete(null); setViewer(null);
    } catch (error) { setImageDeleteError((error as Error).message); }
    finally { setBusy(""); }
  };
  const addGallery = async () => { if (product.images.length + (product.imageUrl ? 1 : 0) >= MAX_PRODUCT_IMAGES) return; setBusy("gallery"); try { const urls = await upload(true); for (const imageUrl of urls) await auth.api(`/products/${product.id}/images`, { method: "POST", body: JSON.stringify({ imageUrl }) }); await reload(); } catch (e) { Alert.alert("Gallery", (e as Error).message); } finally { setBusy(""); } };
  const removeGallery = (imageId: string) => { const image = product.images.find(item => item.id === imageId); if (image) { setImageDeleteError(""); setImageDelete({ id: imageId, url: image.imageUrl }); } };
  const moveGallery = async (index: number, direction: -1 | 1) => { const images = [...product.images].sort((a, b) => a.sortOrder - b.sortOrder); const target = index + direction; if (target < 0 || target >= images.length) return; [images[index], images[target]] = [images[target], images[index]]; setBusy("gallery"); try { await auth.api(`/products/${product.id}/images/reorder`, { method: "PUT", body: JSON.stringify({ imageIdsInOrder: images.map(image => image.id) }) }); await reload(); } catch (e) { Alert.alert("Gallery", (e as Error).message); } finally { setBusy(""); } };

  const toggleMarketplace = async () => { setBusy("marketplace"); try { await auth.api(`/products/${product.id}/marketplace-visibility`, {method:"PATCH",body:JSON.stringify({show:!product.showOnMarketplace})}); await reload(); } catch(e) { Alert.alert(t("productInfo.marketplace"),(e as Error).message); } finally { setBusy(""); } };
  const sortedImages = [...(product.images ?? [])].sort((a, b) => a.sortOrder - b.sortOrder);
  const notSet = bn ? "দেওয়া হয়নি" : "Not set";
  const detail = (label: string, value: string) => <NativeText selectable style={[s.detailValue, productBodyTextStyle]}><NativeText style={[s.detailInlineLabel, productBodyTextStyle]}>{label}: </NativeText>{value || notSet}</NativeText>;
  const inventoryDetail = (label: string, value: string) => <NativeText selectable style={[s.inventoryBody, productBodyTextStyle]}><NativeText style={[s.inventoryLabel, productBodyTextStyle]}>{label}: </NativeText>{value || notSet}</NativeText>;
  return <View style={s.sections}>
    <View style={[s.hero, !source && s.emptyProductImage]}><Pressable disabled={!source} onPress={() => source && setViewer(source)} style={s.heroImagePress}>{source ? <Image source={{ uri: source }} resizeMode="contain" style={s.heroImage} /> : <Ionicons name="cube-outline" size={42} color={colors.muted} />}</Pressable>{owner && <View style={s.heroActions}><Pressable disabled={!!busy} onPress={() => void changeMain()} style={s.imageRound}>{busy === "main" ? <ActivityIndicator size="small" color={colors.primaryDark} /> : <Ionicons name="camera-outline" size={20} color={colors.primaryDark} />}</Pressable>{source && <Pressable disabled={!!busy} onPress={removeMain} style={s.imageRound}><Ionicons name="trash-outline" size={20} color={colors.danger} /></Pressable>}</View>}{uploadPercent !== null && <View style={s.imageUploadOverlay} accessibilityRole="progressbar" accessibilityLabel={t("productInfo.imageUploading")} accessibilityValue={{ min: 0, max: 100, now: uploadPercent }}><View style={s.imageUploadCaption}><Text style={[s.smallMuted, productBodyTextStyle]}>{t(uploadPercent === 100 ? "productInfo.imageSaving" : "productInfo.imageUploading")}</Text><NativeText style={[s.imageUploadPercent, productBodyTextStyle]}>{uploadPercent}%</NativeText></View><View style={s.imageUploadTrack}><View style={[s.imageUploadFill, { width: `${uploadPercent}%` }]} /></View></View>}</View>
    {owner && <View style={s.galleryCard}><ProductSectionTitle>{t("productInfo.images")} ({sortedImages.length + (product.imageUrl ? 1 : 0)}/{MAX_PRODUCT_IMAGES})</ProductSectionTitle><View style={s.gallery}>{sortedImages.map((image, index) => <View key={image.id} style={s.galleryItem}><Pressable onPress={() => setViewer(media(image.imageUrl))}><Image source={{ uri: media(image.imageUrl)! }} resizeMode="contain" style={s.galleryImage} /></Pressable><Pressable disabled={!!busy} onPress={() => void removeGallery(image.id)} style={s.galleryRemove}><Ionicons name="close" size={14} color={colors.white} /></Pressable><View style={s.galleryMove}><Pressable disabled={index === 0 || !!busy} onPress={() => void moveGallery(index, -1)}><Ionicons name="chevron-back" size={17} color={index === 0 ? colors.muted : colors.white} /></Pressable><Pressable disabled={index === sortedImages.length - 1 || !!busy} onPress={() => void moveGallery(index, 1)}><Ionicons name="chevron-forward" size={17} color={index === sortedImages.length - 1 ? colors.muted : colors.white} /></Pressable></View></View>)}{sortedImages.length + (product.imageUrl ? 1 : 0) < MAX_PRODUCT_IMAGES && <Pressable disabled={!!busy} onPress={() => void addGallery()} style={s.galleryAdd}>{busy === "gallery" ? <ActivityIndicator color={colors.primary} /> : <Ionicons name="add" size={25} color={colors.muted} />}</Pressable>}</View><Text style={[s.smallMuted, productBodyTextStyle]}>{t("productInfo.galleryHelp")}</Text></View>}
    <View style={[s.card,s.productDetailsCard]}>
      <View style={s.cardHead}><ProductSectionTitle>{t("productInfo.details")}</ProductSectionTitle>{owner && <Pressable accessibilityRole="button" accessibilityLabel={bn ? "পণ্য সম্পাদনা" : "Edit product"} onPress={edit} style={s.roundAction}><Ionicons name="create-outline" size={21} color={colors.primaryDark}/></Pressable>}</View>
      {detail(t("productInfo.name"),product.name)}
      {detail(bn ? "ক্যাটাগরি" : "Category",product.categoryName)}
      {detail(t("SKU Code"),product.sku)}
      {product.variants.length ? product.variants.map(variant => <View key={variant.id}>{detail(`${t("Barcode")}${product.variants.length > 1 ? ` (${variantName(variant)})` : ""}`,variant.barcode)}</View>) : detail(t("Barcode"),notSet)}
      {detail(t("productInfo.warranty"),product.warrantyDurationValue ? `${product.warrantyDurationValue} ${bn ? ({DAYS:"দিন",MONTHS:"মাস",YEARS:"বছর"}[product.warrantyDurationUnit ?? ""] ?? "") : (product.warrantyDurationUnit ?? "").toLowerCase()}` : notSet)}
      {detail(t("productInfo.description"),product.description ?? "")}
      {detail(bn ? "নোট" : "Notes",product.note ?? "")}
    </View>
    <ProductBrandField key={`${product.id}:${auth.session?.businessId}`} productId={product.id} editable={owner}/>
    {owner && (needsPrice || out) && <View style={s.card}>
      <ProductSectionTitle>{needsPrice ? (bn ? "পরবর্তী ধাপ: বিক্রয়মূল্য নির্ধারণ" : "Next: Set selling price") : (bn ? "পরবর্তী ধাপ: স্টক যোগ করুন" : "Next: Add stock")}</ProductSectionTitle>
      <Text style={[s.smallMuted, productBodyTextStyle]}>{needsPrice ? (bn ? "বিক্রির আগে পণ্যের দাম নির্ধারণ করুন।" : "Set a price before selling this product.") : (bn ? "পণ্যের পরিমাণ যোগ করুন এবং ক্রয়মূল্য নির্ধারণ করুন।" : "Add the product quantity and record its purchase cost.")}</Text>
      <Pressable accessibilityRole="button" onPress={() => go(needsPrice ? "prices" : "stock")} style={({pressed}) => [s.stockManagementLink, pressed && s.disabled]}><Text style={[s.actionText, productBodyTextStyle]}>{needsPrice ? (bn ? "দাম নির্ধারণ করুন" : "Set price") : (bn ? "স্টক যোগ করুন" : "Add stock")}</Text><Ionicons name="arrow-forward" size={17} color={colors.primaryDark}/></Pressable>
    </View>}
    <View style={[s.stockCard,out ? s.stockOut : low ? s.stockLow : s.stockGood]}>
      <ProductSectionTitle>{bn ? "মূল্য ও স্টক" : "Price & Inventory"}</ProductSectionTitle>
      {product.variants.map(variant => <View key={variant.id} style={{gap:5}}>
        {product.variants.length > 1 && <NativeText style={[s.inventoryLabel, productBodyTextStyle]}>{variantName(variant)}</NativeText>}
        {inventoryDetail(bn ? "বিক্রয়মূল্য" : "Selling price",(variant.priceOverride ?? product.sellingPrice) > 0 ? money(variant.priceOverride ?? product.sellingPrice) : notSet)}
        {owner && inventoryDetail(bn ? "ক্রয়মূল্য" : "Purchase cost",Number(variant.avgLandedCost) > 0 ? money(variant.avgLandedCost) : notSet)}
      </View>)}
      <View style={s.stockRow}><Text style={[s.inventoryQuantity, productBodyTextStyle]}>{totalStock} <Text style={[s.inventoryBody, productBodyTextStyle]}>{product.unitCode}</Text></Text><Text style={[s.stockBadge,out ? s.badgeDanger : low ? s.badgeWarning : s.badgeSuccess,productBodyTextStyle]}>{t(out ? "productInfo.outOfStock" : low ? "productInfo.lowStock" : "productInfo.inStock")}</Text></View>
      {inventoryDetail(t("productInfo.lowStockAlert"),`${product.lowStockThreshold} ${product.unitCode}`)}
      {canAdjust && <Pressable accessibilityRole="button" onPress={() => go("stock")} style={({pressed}) => [s.stockManagementLink, pressed && s.disabled]}><Text style={[s.actionText, productBodyTextStyle]}>{bn ? "স্টক ব্যবস্থাপনা" : "Stock management"}</Text><Ionicons name="arrow-forward" size={17} color={colors.primaryDark}/></Pressable>}
    </View>
    {owner && <View style={s.marketToggleCard}><Ionicons name="bag-handle-outline" size={22} color={colors.primaryDark}/><View style={s.grow}><Text style={s.sectionTitle}>{t("productInfo.marketplace")}</Text><Text style={[s.smallMuted,productBodyTextStyle]}>{t("productInfo.marketplaceHelp")}</Text></View><Pressable accessibilityRole="switch" accessibilityLabel={t("productInfo.marketplace")} accessibilityState={{checked:!!product.showOnMarketplace,disabled:busy === "marketplace"}} disabled={busy === "marketplace"} onPress={() => void toggleMarketplace()} style={[s.infoToggle,product.showOnMarketplace && s.infoToggleOn]}><View style={[s.infoToggleKnob,product.showOnMarketplace && s.infoToggleKnobOn]}/></Pressable></View>}
    {!!orders.length && <View style={s.orderHistory}><View style={s.cardHead}><ProductSectionTitle>Order History</ProductSectionTitle><Pressable onPress={() => router.push("/orders")}><Text style={[s.actionText, productBodyTextStyle]}>View all orders</Text></Pressable></View>{orders.slice(0, 5).map(order => { const qty = order.items.filter(item => item.productId === product.id).reduce((sum, item) => sum + Number(item.qty), 0); return <Pressable key={order.id} onPress={() => router.push({ pathname: "/orders/[id]", params: { id: order.id } })} style={s.productOrderRow}><View style={s.grow}><Text style={[s.orderNo, productBodyTextStyle]}>#{order.orderNo}</Text><Text style={[s.smallMuted, productBodyTextStyle]}>{new Date(order.createdAt).toLocaleDateString()} · {qty} {product.unitCode}</Text></View><Text style={[s.orderAmount, productBodyTextStyle]}>{money(order.totalAmount)}</Text><Text style={[s.paymentPill, order.paymentStatus === "PAID" ? s.paymentPaid : s.paymentDue,productBodyTextStyle]}>{order.paymentStatus === "PAID" ? "Paid" : "Due"}</Text></Pressable>; })}</View>}
    <ConfirmDialog visible={!!imageDelete} title={t("productInfo.imageDeleteTitle")} message={imageDeleteError || t("productInfo.imageDeleteMessage")} confirmLabel={t("Delete")} cancelLabel={t("Cancel")} destructive busy={!!busy} onConfirm={() => void confirmImageDelete()} onCancel={() => { setImageDelete(null); if (imageDelete?.detached) void reload(); }} />
    <Modal visible={!!viewer} transparent animationType="fade" onRequestClose={() => setViewer(null)}><Pressable onPress={() => setViewer(null)} style={s.imageViewer}><SafeAreaView style={s.imageViewerCard}><View style={s.cardHead}><NativeText numberOfLines={1} style={s.sectionTitle}>{product.name}</NativeText><Ionicons name="close" size={25} color={colors.heading} /></View>{viewer && <Image source={{ uri: viewer }} resizeMode="contain" style={s.viewerImage} />}</SafeAreaView></Pressable></Modal>
  </View>;
}
function VariantRow({ variant, product }: { variant: Variant; product: Product }) { const source = media(variant.imageUrl || product.imageUrl); const price = variant.priceOverride ?? product.sellingPrice; return <View style={s.variantRow}>{source ? <Image source={{ uri: source }} style={s.variantImage} /> : <View style={s.variantImage}><Ionicons name="cube-outline" size={18} color={colors.muted} /></View>}<View style={s.grow}><Text numberOfLines={1} style={s.variantName}>{variantName(variant)}</Text><Text style={s.variantSku}>{variant.sku}</Text></View><View style={s.right}><Text style={s.variantPrice}>{money(price)}</Text><Text style={s.variantStock}>{variant.stock ?? 0} in stock</Text></View></View>; }
function Variants({ product, auth, owner, canAdjust, reload, price, stock }: { product: Product; auth: ReturnType<typeof useAuth>; owner: boolean; canAdjust: boolean; reload: () => Promise<void>; price: (variant: Variant) => void; stock: (variant: Variant) => void }) {
  const [labelQty, setLabelQty] = useState("1"); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [showAdd, setShowAdd] = useState(false); const [showSplit, setShowSplit] = useState(false); const [categoryFields, setCategoryFields] = useState<CategoryField[]>([]);
  const [name, setName] = useState(""); const [values, setValues] = useState<Record<string, string>>({}); const [imageUrl, setImageUrl] = useState<string | null>(null); const [note, setNote] = useState(""); const [override, setOverride] = useState(""); const [qty, setQty] = useState(""); const [cost, setCost] = useState("");
  const [splitRows, setSplitRows] = useState([{ name: "", qty: "" }, { name: "", qty: "" }]);
  const images = Array.from(new Set([product.imageUrl, ...(product.images ?? []).map(item => item.imageUrl)].filter(Boolean))) as string[];
  const source = product.variants.length === 1 ? product.variants[0] : null; const sourceStock = Number(source?.stock ?? 0); const needsSplit = !!source && sourceStock > 0; const splitTotal = splitRows.reduce((sum, row) => sum + (Number(row.qty) || 0), 0); const splitMatches = Math.abs(splitTotal - sourceStock) < .0005;
  useEffect(() => { if (owner) auth.api<{ fields: CategoryField[] }>(`/categories/${product.categoryId}`).then(value => setCategoryFields(value.fields.filter(field => field.isVariant))).catch(() => setCategoryFields([])); }, [product.categoryId, owner]);
  const run = async (action: () => Promise<void>) => { setBusy(true); setError(""); try { await action(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  const chooseImage = (variant: Variant, next: string | null) => run(async () => { await auth.api(`/products/${product.id}/variants/${variant.id}`, { method: "PUT", body: JSON.stringify({ imageUrl: next, note: variant.note, priceOverride: variant.priceOverride, isDefault: variant.isDefault, rowVer: variant.rowVer }) }); await reload(); });
  const add = () => run(async () => { if (Number(qty) <= 0) throw new Error("Initial stock must be greater than zero."); if (cost === "" || Number(cost) < 0) throw new Error("Enter a valid buy price."); await auth.api(`/products/${product.id}/variants`, { method: "POST", body: JSON.stringify({ variantValuesJson: JSON.stringify(name.trim() ? { Name: name.trim(), ...values } : values), barcode: null, imageUrl, note: note.trim() || null, priceOverride: override ? Number(override) : null, isDefault: false, qty: Number(qty), costPrice: Number(cost), branchId: auth.session?.branchId }) }); setShowAdd(false); setName(""); setValues({}); setImageUrl(null); setNote(""); setOverride(""); setQty(""); setCost(""); await reload(); });
  const split = () => run(async () => { if (!splitRows.every(row => row.name.trim() && Number(row.qty) > 0)) throw new Error("Enter a name and quantity for every variant."); if (!splitMatches) throw new Error(`Variant quantities must total ${sourceStock}.`); await auth.api(`/products/${product.id}/variants/split`, { method: "POST", body: JSON.stringify({ sourceVariantId: source!.id, items: splitRows.map(row => ({ values: { Name: row.name.trim() }, qty: Number(row.qty) })), branchId: auth.session?.branchId }) }); setShowSplit(false); await reload(); });
  const printLabels = async (variantId?: string) => { if (Platform.OS !== "web" || typeof window === "undefined") { Alert.alert("Barcode labels", "Barcode PDF download is currently available from the web version."); return; } setBusy(true); setError(""); try { const query = new URLSearchParams({ qty: String(Math.max(1, Number(labelQty) || 1)) }); if (variantId) query.set("variantId", variantId); const response = await fetch(`${API_URL}/products/${product.id}/barcode-labels?${query}`, { headers: { Authorization: `Bearer ${auth.session?.accessToken}`, ...(auth.session?.businessId ? { "X-Business-Id": auth.session.businessId } : {}), ...(auth.session?.branchId ? { "X-Branch-Id": auth.session.branchId } : {}) } }); if (!response.ok) throw new Error("Could not generate barcode labels."); const url = URL.createObjectURL(await response.blob()); window.open(url, "_blank"); setTimeout(() => URL.revokeObjectURL(url), 60000); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <View style={s.sections}>
    {owner && <View style={s.labelToolbar}><Text style={s.smallMuted}>Qty per label</Text><TextInput value={labelQty} onChangeText={setLabelQty} keyboardType="number-pad" style={s.qtyInput} /><Pressable disabled={busy} onPress={() => void printLabels()} style={s.outlineButton}><Text style={s.actionText}>🖨 Print All Labels</Text></Pressable></View>}
    {!!error && <Text style={s.errorBox}>{error}</Text>}
    {product.variants.map(variant => { const currentImage = media(variant.imageUrl || product.imageUrl); return <View key={variant.id} style={s.variantDetailCard}>
      {owner && <><View style={s.variantHero}>{currentImage ? <Image source={{ uri: currentImage }} resizeMode="contain" style={s.heroImage} /> : <Ionicons name="image-outline" size={45} color={colors.muted} />}</View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.imageChoices}><Pressable onPress={() => void chooseImage(variant, null)} style={s.removeImage}><Ionicons name="trash-outline" size={18} color={colors.danger} /><Text style={s.deleteText}>Use product photo</Text></Pressable>{images.map(value => <Pressable key={value} onPress={() => void chooseImage(variant, value)} style={[s.imageChoice, variant.imageUrl === value && s.imageChoiceActive]}><Image source={{ uri: media(value)! }} resizeMode="contain" style={s.choiceImage} /></Pressable>)}</ScrollView><Text style={s.smallMuted}>Optional — falls back to the product photo if not set</Text></>}
      <View style={s.variantMeta}><View style={s.grow}><Text style={s.variantName}>{variantName(variant)}</Text><Text style={s.smallMuted}>SKU: {variant.sku}</Text><Text style={s.smallMuted}>Barcode: {variant.barcode}</Text>{variant.note && <Text style={s.note}>{variant.note}</Text>}</View><View style={s.right}>{variant.priceOverride != null ? <Text style={s.priceAccent}>{money(variant.priceOverride)}</Text> : <Text style={s.smallMuted}>(base price)</Text>}{owner && Number(variant.avgLandedCost ?? 0) > 0 && <Text style={s.smallMuted}>Cost: {money(variant.avgLandedCost)}</Text>}<Text style={s.smallMuted}>Stock: {variant.stock ?? 0}</Text></View></View>
      {(owner || canAdjust) && <View style={s.variantActions}>{owner && <Pressable onPress={() => price(variant)} style={s.offerButton}><Text style={s.actionText}>Price Settings →</Text></Pressable>}{canAdjust && <Pressable onPress={() => stock(variant)} style={s.stockButton}><Text style={s.stockButtonText}>Adjust Stock →</Text></Pressable>}{owner && <Pressable disabled={busy} onPress={() => void printLabels(variant.id)} style={s.labelButton}><Text style={s.smallMuted}>🖨 Label</Text></Pressable>}</View>}
    </View>; })}
    {owner && !showAdd && !showSplit && <Pressable onPress={() => needsSplit ? setShowSplit(true) : setShowAdd(true)} style={s.dashedButton}><Text style={s.actionText}>{needsSplit ? "Split into Variants" : "Add Variant"}</Text></Pressable>}
    {owner && showSplit && source && <View style={s.variantForm}><Text style={s.sectionTitle}>Split Existing Stock into Variants</Text><Text style={s.muted}>Allocate all {sourceStock} existing units between the new variants.</Text>{splitRows.map((row, index) => <View key={index} style={s.splitRow}><TextInput value={row.name} onChangeText={value => setSplitRows(current => current.map((item, i) => i === index ? { ...item, name: value } : item))} placeholder={`Variant ${index + 1} name`} placeholderTextColor={colors.muted} style={[s.input, s.grow]} /><TextInput value={row.qty} onChangeText={value => setSplitRows(current => current.map((item, i) => i === index ? { ...item, qty: value } : item))} placeholder="Qty" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={s.splitQty} />{splitRows.length > 2 && <Pressable onPress={() => setSplitRows(current => current.filter((_, i) => i !== index))}><Ionicons name="close-circle" size={22} color={colors.danger} /></Pressable>}</View>)}<Pressable onPress={() => setSplitRows(current => [...current, { name: "", qty: "" }])} style={s.dashedSmall}><Text style={s.actionText}>Add another variant</Text></Pressable><Text style={[s.splitTotal, splitMatches ? s.positive : s.negative]}>Total: {splitTotal} / {sourceStock}</Text><View style={s.formActions}><Pressable onPress={() => setShowSplit(false)} style={s.cancelButton}><Text style={s.muted}>Cancel</Text></Pressable><Pressable disabled={busy || !splitMatches} onPress={() => void split()} style={[s.primary, s.grow, (busy || !splitMatches) && s.disabled]}><Text style={s.primaryText}>Save Variants</Text></Pressable></View></View>}
    {owner && showAdd && <View style={s.variantForm}><Text style={s.sectionTitle}>Add New Variant</Text><TextInput value={name} onChangeText={setName} placeholder="Variant Name (optional)" placeholderTextColor={colors.muted} style={s.input} />{categoryFields.map(field => <TextInput key={field.id} value={values[field.name] ?? ""} onChangeText={value => setValues(current => ({ ...current, [field.name]: value }))} placeholder={field.name} placeholderTextColor={colors.muted} style={s.input} />)}<TextInput value={override} onChangeText={setOverride} placeholder="Price override (optional)" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={s.input} /><View style={s.splitRow}><TextInput value={qty} onChangeText={setQty} placeholder="Initial stock" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={[s.input, s.grow]} /><TextInput value={cost} onChangeText={setCost} placeholder="Buy price" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={[s.input, s.grow]} /></View><TextInput value={note} onChangeText={setNote} placeholder="Details (optional)" placeholderTextColor={colors.muted} multiline style={[s.input, s.textarea]} />{!!images.length && <><Text style={s.smallMuted}>Choose existing image (optional)</Text><ScrollView horizontal contentContainerStyle={s.imageChoices}>{images.map(value => <Pressable key={value} onPress={() => setImageUrl(value)} style={[s.imageChoice, imageUrl === value && s.imageChoiceActive]}><Image source={{ uri: media(value)! }} resizeMode="contain" style={s.choiceImage} /></Pressable>)}</ScrollView></>}<View style={s.formActions}><Pressable onPress={() => setShowAdd(false)} style={s.cancelButton}><Text style={s.muted}>Cancel</Text></Pressable><Pressable disabled={busy} onPress={() => void add()} style={[s.primary, s.grow, busy && s.disabled]}><Text style={s.primaryText}>Add Variant</Text></Pressable></View></View>}
  </View>;
}
function Prices({ product, auth, reload, initialVariantId, manageCost }: { product: Product; auth: ReturnType<typeof useAuth>; reload: () => Promise<void>; initialVariantId?: string | null; manageCost: () => void }) {
  const [priceEditOpen, setPriceEditOpen] = useState(false);
  const [priceInput, setPriceInput] = useState("");
  const [priceError, setPriceError] = useState("");
  const [priceSaving, setPriceSaving] = useState(false);
  const [discountPickerOpen, setDiscountPickerOpen] = useState(false);
  const [discounts, setDiscounts] = useState<ReusableDiscount[]>([]);
  const [discountLoading, setDiscountLoading] = useState(false);
  const [discountError, setDiscountError] = useState("");
  const [discountNotice, setDiscountNotice] = useState("");
  const [removeDiscountOpen, setRemoveDiscountOpen] = useState(false);
  const [removeAssignment, setRemoveAssignment] = useState<ActiveDiscountAssignment | null>(null);
  const [removeDiscountBusy, setRemoveDiscountBusy] = useState(false);
  const [removeDiscountError, setRemoveDiscountError] = useState("");
  const [selectedDiscountId, setSelectedDiscountId] = useState<string | null>(null);
  const [applyingDiscountId, setApplyingDiscountId] = useState<string | null>(null);
  const canSeeConfidentialPrices = ["OWNER", "MANAGER"].includes(auth.session?.user.role ?? "");
  const active = product.variants.find(item => item.id === initialVariantId) ?? product.variants[0];
  const sellingPrice = active?.priceOverride ?? product.sellingPrice;
  const hasActiveOffer = Number(active?.activeOfferPercent ?? 0) > 0 && Number(active?.offerRegularPrice ?? 0) > sellingPrice;
  const totalCost = Number(active?.avgLandedCost ?? 0) + Number(product.packagingCostPerUnit ?? 0);
  const costNotSet = Number(active?.stock ?? 0) > 0 && Number(active?.avgLandedCost ?? 0) === 0;
  const profit = sellingPrice - totalCost;
  const saveSellingPrice = async () => {
    const value = Number(priceInput);
    if (!priceInput.trim() || !Number.isFinite(value) || value < 0) { setPriceError("Enter a valid selling price."); return; }
    if (hasActiveOffer) { setPriceError("Remove the active discount before changing this price."); return; }
    setPriceSaving(true); setPriceError("");
    try {
      if (active && (active.priceOverride != null || !active.isDefault)) {
        await auth.api(`/products/${product.id}/variants/${active.id}`, { method: "PUT", body: JSON.stringify({ imageUrl: active.imageUrl, note: active.note, priceOverride: value, isDefault: active.isDefault, rowVer: active.rowVer }) });
      } else {
        await auth.api(`/products/${product.id}`, { method: "PUT", body: JSON.stringify({ categoryId: product.categoryId, name: product.name, imageUrl: product.imageUrl, description: product.description, defectNotes: product.defectNotes, unitCode: product.unitCode, sellingPrice: value, marketPrice: product.marketPrice, packagingCostPerUnit: product.packagingCostPerUnit ?? 0, lowStockThreshold: product.lowStockThreshold, attributesJson: product.attributesJson, note: product.note, status: product.status, rowVer: product.rowVer, warrantyDurationValue: product.warrantyDurationValue, warrantyDurationUnit: product.warrantyDurationUnit, wholesaleMinQty: product.wholesaleMinQty, wholesaleUnitPrice: product.wholesaleUnitPrice, wholesaleNote: product.wholesaleNote, sku: product.sku }) });
      }
      await reload(); setPriceEditOpen(false);
    } catch (e) { setPriceError((e as Error).message); }
    finally { setPriceSaving(false); }
  };
  const openDiscountPicker = async () => {
    setDiscountPickerOpen(true);
    setDiscountLoading(true);
    setDiscountError("");
    try {
      const result = await auth.api<ReusableDiscount[]>("/discounts");
      const now = Date.now();
      const available = result.filter(item => !item.isArchived && (!item.endDate || new Date(item.endDate).getTime() >= now));
      setDiscounts(available);
      setSelectedDiscountId(current => available.some(item => item.id === current) ? current : null);
    } catch (e) { setDiscountError((e as Error).message); }
    finally { setDiscountLoading(false); }
  };
  const applyDiscount = async () => {
    const discount = discounts.find(item => item.id === selectedDiscountId);
    if (!discount) return;
    setApplyingDiscountId(discount.id);
    setDiscountError("");
    try {
      const result = await auth.api<{ productCount: number; variantCount: number; activatedCount: number; scheduledCount: number }>(`/discounts/${discount.id}/apply`, { method: "POST", body: JSON.stringify({ allProducts: false, categoryIds: [], productIds: [product.id] }) });
      await reload();
      setDiscountPickerOpen(false);
      setDiscountNotice(result.scheduledCount > 0
        ? `${discount.name} is scheduled for ${result.variantCount} variants.`
        : `${discount.name} applied to ${result.productCount} product${result.productCount === 1 ? "" : "s"}.`);
    } catch (e) { setDiscountError((e as Error).message); }
    finally { setApplyingDiscountId(null); }
  };
  const openRemoveDiscount = async () => {
    if (!active) return;
    setRemoveDiscountOpen(true); setRemoveDiscountBusy(true); setRemoveDiscountError(""); setRemoveAssignment(null);
    try {
      const assignments = await auth.api<ActiveDiscountAssignment[]>("/discounts/active-assignments");
      const assignment = assignments.find(item => item.variantId === active.id);
      if (!assignment) throw new Error("The active discount could not be found. Refresh the product and try again.");
      setRemoveAssignment(assignment);
    } catch (e) { setRemoveDiscountError((e as Error).message); }
    finally { setRemoveDiscountBusy(false); }
  };
  const removeCurrentDiscount = async () => {
    if (!removeAssignment) return;
    setRemoveDiscountBusy(true); setRemoveDiscountError("");
    try {
      await auth.api(`/discounts/${removeAssignment.discountId}/applied-variants/${removeAssignment.variantId}`, { method: "DELETE" });
      await reload();
      setDiscountNotice(`${removeAssignment.discountName} removed from ${active ? variantName(active) : product.name}.`);
      setRemoveDiscountOpen(false);
    } catch (e) { setRemoveDiscountError((e as Error).message); }
    finally { setRemoveDiscountBusy(false); }
  };

  return <View style={s.sections}>
    <View style={s.sellCard}>
      <View style={s.sellHeader}><Text style={s.sellCaption}>Current Selling Price</Text><View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>{hasActiveOffer && <Text style={s.offerBadge}>{active?.activeOfferPercent}% OFF</Text>}{auth.session?.user.role === "OWNER" && <Pressable accessibilityRole="button" accessibilityLabel="Edit current selling price" onPress={() => { setPriceInput(String(sellingPrice)); setPriceError(""); setPriceEditOpen(true); }} style={{ padding: 5 }}><Ionicons name="create-outline" size={19} color={colors.white}/></Pressable>}</View></View>
      <View style={s.sellPriceRow}><Text style={[s.sellPrice, hasActiveOffer && { color: colors.primary }]}>{money(sellingPrice)}</Text>{hasActiveOffer && <Text style={s.sellOldPrice}>{money(active?.offerRegularPrice)}</Text>}</View>
      {canSeeConfidentialPrices && !costNotSet && <View style={s.costRows}>
        <PriceLine label="Product Purchase Cost" value={money(totalCost)} onEdit={auth.session?.user.role === "OWNER" ? manageCost : undefined} />
        <PriceLine label="Profit" value={money(profit)} positive={profit >= 0} />
      </View>}
    </View>
    <PopupSheet visible={priceEditOpen} onClose={() => !priceSaving && setPriceEditOpen(false)} title="Edit selling price">
      <View style={{ padding: 16, gap: 12 }}>
        <Text style={{ color: colors.heading, fontSize: 12, fontWeight: "700" }}>{active ? `${product.name} · ${variantName(active)}` : product.name}</Text>
        {hasActiveOffer && <Text style={{ color: colors.dangerText, fontSize: 12 }}>Remove the active discount before changing this price.</Text>}
        <Text style={{ color: colors.secondary, fontSize: 12 }}>Selling price (৳)</Text>
        <TextInput accessibilityLabel="Selling price" value={priceInput} onChangeText={setPriceInput} keyboardType="decimal-pad" autoFocus selectTextOnFocus style={[s.input, { fontSize: 17 }]} />
        {!!priceError && <Text style={s.errorBox}>{priceError}</Text>}
        <Pressable accessibilityRole="button" disabled={priceSaving || hasActiveOffer} onPress={() => void saveSellingPrice()} style={[s.primary, (priceSaving || hasActiveOffer) && s.disabled]}>{priceSaving ? <ActivityIndicator color={colors.white}/> : <Text style={s.primaryText}>Save price</Text>}</Pressable>
      </View>
    </PopupSheet>
    {auth.session?.user.role === "OWNER" && <Pressable accessibilityRole="button" onPress={() => void openDiscountPicker()} style={s.primary}>
      <Text style={s.primaryText}>Set Discount Offer...</Text>
    </Pressable>}
    {auth.session?.user.role === "OWNER" && hasActiveOffer && <Pressable accessibilityRole="button" onPress={() => void openRemoveDiscount()} style={{ minHeight: 44, alignItems: "center", justifyContent: "center", borderWidth: 1, borderColor: colors.danger, borderRadius: 10, backgroundColor: colors.white }}><Text style={{ color: colors.dangerText, fontSize: 13, fontWeight: "700" }}>Remove current discount</Text></Pressable>}
    {!!discountNotice && <Text style={s.discountNotice}>{discountNotice}</Text>}
    <PopupSheet visible={removeDiscountOpen} onClose={() => !removeDiscountBusy && setRemoveDiscountOpen(false)} title={`Remove current discount (${active?.activeOfferPercent ?? 0}% discount)`}>
      <View style={{ padding: 16, gap: 12 }}>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 12, borderWidth: 1, borderColor: colors.divider, borderRadius: 12, padding: 10, backgroundColor: colors.white }}>
          <View style={{ width: 72, height: 72, alignItems: "center", justifyContent: "center", borderRadius: 9, overflow: "hidden", backgroundColor: colors.cardSecondary }}>{media(active?.imageUrl || product.imageUrl) ? <Image source={{ uri: media(active?.imageUrl || product.imageUrl)! }} resizeMode="cover" style={{ width: 72, height: 72 }}/>: <Ionicons name="cube-outline" size={30} color={colors.muted}/>}</View>
          <View style={{ flex: 1, gap: 3 }}><Text style={{ color: colors.heading, fontSize: 14, fontWeight: "700" }}>{product.name}</Text><Text style={{ color: colors.secondary, fontSize: 12 }}>{active?.sku ?? product.sku}{active ? ` · ${variantName(active)}` : ""}</Text><Text style={{ color: colors.primaryDark, fontSize: 12, fontWeight: "700" }}>{removeAssignment?.discountName ?? active?.activeOfferName ?? "Current offer"} · {active?.activeOfferPercent}% OFF</Text></View>
        </View>
        <Text style={{ color: colors.heading, fontSize: 13 }}>Remove {removeAssignment?.discountName ?? active?.activeOfferName ?? "the discount"} from {active?.sku ?? product.sku}? The regular selling price will be restored.</Text>
        <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", borderRadius: 10, backgroundColor: colors.primaryLight, padding: 12 }}><Text style={{ color: colors.secondary, fontSize: 12 }}>Price after removal</Text><Text style={{ color: colors.primaryDark, fontSize: 18, fontWeight: "800" }}>{money(active?.offerRegularPrice)}</Text></View>
        {!!removeDiscountError && <Text style={s.errorBox}>{removeDiscountError}</Text>}
        <View style={{ flexDirection: "row", gap: 8 }}><Pressable disabled={removeDiscountBusy} onPress={() => setRemoveDiscountOpen(false)} style={{ flex: 1, minHeight: 45, alignItems: "center", justifyContent: "center", borderWidth: 1, borderColor: colors.border, borderRadius: 11 }}><Text style={s.actionText}>Cancel</Text></Pressable><Pressable accessibilityRole="button" disabled={removeDiscountBusy || !removeAssignment} onPress={() => void removeCurrentDiscount()} style={[s.primary, { flex: 1, backgroundColor: colors.danger }, (removeDiscountBusy || !removeAssignment) && s.disabled]}>{removeDiscountBusy ? <ActivityIndicator color={colors.white}/> : <Text style={s.primaryText}>Remove discount</Text>}</Pressable></View>
      </View>
    </PopupSheet>
    <PopupSheet visible={discountPickerOpen} onClose={() => !applyingDiscountId && setDiscountPickerOpen(false)} title="Set Discount Offer" headerAction={<Pressable accessibilityRole="button" onPress={() => { setDiscountPickerOpen(false); router.push({ pathname: "/more/discounts", params: { productId: product.id } }); }} style={s.discountManageLink}><Text style={s.discountManageText}>Go to discount manager</Text></Pressable>}>
      <ScrollView style={s.discountPickerScroll} contentContainerStyle={s.discountPickerList}>
        {discountLoading ? <View style={s.discountPickerState}><ActivityIndicator color={colors.primary}/><Text style={s.muted}>Loading discounts...</Text></View>
          : discounts.length === 0 ? <View style={s.discountPickerState}><Ionicons name="pricetag-outline" size={26} color={colors.muted}/><Text style={s.sectionTitle}>No available discounts</Text><Text style={s.muted}>Create a reusable discount from the discount manager.</Text></View>
          : discounts.map(discount => { const selected = selectedDiscountId === discount.id; return <Pressable key={discount.id} accessibilityRole="radio" accessibilityState={{ selected }} disabled={!!applyingDiscountId} onPress={() => { setSelectedDiscountId(discount.id); setDiscountError(""); }} style={[s.discountOption, selected && s.discountOptionSelected, !!applyingDiscountId && s.disabled]}>
            <View style={[s.discountRadio, selected && s.discountRadioSelected]}>{selected && <View style={s.discountRadioDot}/>}</View>
            <View style={s.discountPercentBadge}><Text style={s.discountPercentText}>{discount.percent}%</Text></View>
            <View style={s.grow}><Text style={s.variantName}>{discount.name}</Text><Text style={s.smallMuted}>Starts {new Date(discount.startDate).toLocaleDateString()}{discount.endDate ? ` · Ends ${new Date(discount.endDate).toLocaleDateString()}` : " · No end date"}</Text></View>
          </Pressable>; })}
        {!!discountError && <Text style={s.errorBox}>{discountError}</Text>}
      </ScrollView>
      {discounts.length > 0 && <View style={s.discountPickerFooter}><Pressable accessibilityRole="button" disabled={!selectedDiscountId || !!applyingDiscountId || discountLoading} onPress={() => void applyDiscount()} style={[s.primary, (!selectedDiscountId || !!applyingDiscountId || discountLoading) && s.disabled]}>{applyingDiscountId ? <ActivityIndicator color={colors.white}/> : <Text style={s.primaryText}>Apply This Offer</Text>}</Pressable></View>}
    </PopupSheet>
    {costNotSet && <Pressable onPress={manageCost} style={s.costWarning}><Text style={s.costWarningTitle}>Purchase price is not set</Text><Text style={s.costWarningText}>Manage Purchase Cost →</Text></Pressable>}
  </View>;
}
function PriceLine({ label, value, onEdit, positive }: { label: string; value: string; onEdit?: () => void; positive?: boolean }) {
  const content = <><Text style={s.priceLineLabel}>{label}</Text><View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}><Text style={[s.priceLineValue, positive === true && s.profitPositive, positive === false && s.profitNegative]}>{value}</Text>{onEdit && <Ionicons name="create-outline" size={15} color="#FED7AA" />}</View></>;
  return onEdit
    ? <Pressable accessibilityRole="button" accessibilityLabel={`Edit ${label}`} onPress={onEdit} style={[s.priceLine, s.compactPriceLine]}>{content}</Pressable>
    : <View style={[s.priceLine, s.compactPriceLine]}>{content}</View>;
}
function PriceSheet({ visible, title, close, children }: { visible: boolean; title: string; close: () => void; children: React.ReactNode }) {
  const { width } = useWindowDimensions();
  const mobile = width < 768;
  return <Modal visible={visible} transparent animationType="fade" onRequestClose={close}>
    <View style={[s.overlay, mobile && s.priceMobileOverlay]}>
      <Pressable accessibilityLabel="Close price panel" onPress={close} style={StyleSheet.absoluteFill} />
      <SafeAreaView style={[s.priceModal, mobile && s.priceMobileModal]}>
        {mobile && <View style={s.sheetHandle} />}
        <View style={s.modalHead}><Pressable accessibilityLabel="Close" onPress={close} style={s.sheetClose}><Ionicons name="close" size={22} color={colors.secondary} /></Pressable><Text style={[s.modalTitle, s.grow]}>{title}</Text></View>
        <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={s.priceModalContent}>{children}</ScrollView>
      </SafeAreaView>
    </View>
  </Modal>;
}

function Stock({ product, auth, reload, initialVariantId }: { product: Product; auth: ReturnType<typeof useAuth>; reload: () => Promise<void>; initialVariantId?: string | null }) {
  type StockMode = "ADD" | "DEDUCT" | "RECOUNT"; type StockReason = "EXISTING_STOCK" | "FOUND_EXTRA" | "OTHER" | "DAMAGED" | "LOST_THEFT" | "RECOUNT";
  const reasons: Record<StockMode, StockReason[]> = { ADD: ["EXISTING_STOCK", "FOUND_EXTRA", "OTHER"], DEDUCT: ["DAMAGED", "LOST_THEFT", "OTHER"], RECOUNT: ["RECOUNT"] };
  const reasonLabel: Record<StockReason, string> = { EXISTING_STOCK: "Existing stock", FOUND_EXTRA: "Found extra", OTHER: "Other", DAMAGED: "Damaged", LOST_THEFT: "Lost / theft", RECOUNT: "Recount" };
  const [variantId, setVariantId] = useState(initialVariantId ?? product.variants[0]?.id ?? ""); const [mode, setMode] = useState<StockMode | null>(null); const [reason, setReason] = useState<StockReason>("EXISTING_STOCK"); const [value, setValue] = useState("1"); const [note, setNote] = useState(""); const [history, setHistory] = useState<Adjustment[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const active = product.variants.find(item => item.id === variantId) ?? product.variants[0];
  useEffect(() => { if (active) auth.api<Adjustment[]>(`/products/variants/${active.id}/stock-adjustments`).then(setHistory).catch(() => setHistory([])); }, [active?.id]);
  const currentStock = Number(active?.stock ?? 0); const entered = Number(value) || 0; const projected = mode === "DEDUCT" ? Math.max(0, currentStock - entered) : mode === "RECOUNT" ? entered : currentStock + entered;
  const close = () => { setMode(null); setValue("1"); setNote(""); setError(""); };
  const open = (next: StockMode) => { setMode(next); setReason(reasons[next][0]); setValue(next === "RECOUNT" ? String(currentStock) : "1"); setNote(""); setError(""); };
  const step = (change: number) => { const minimum = mode === "RECOUNT" ? 0 : 1; if (mode === "DEDUCT" && currentStock < minimum) return; const next = Math.max(minimum, (Number(value) || 0) + change); setValue(String(mode === "DEDUCT" ? Math.min(currentStock, next) : next)); };
  const submit = async () => { if (!mode || !active) return; const qty = Number(value); const minimum = mode === "RECOUNT" ? 0 : 1; if (!value || !Number.isFinite(qty) || qty < minimum) { setError(mode === "RECOUNT" ? "Enter a stock quantity of zero or more." : "Quantity must be at least 1."); return; } if (mode === "DEDUCT" && qty > currentStock) { setError(`You can deduct at most ${Math.max(0, currentStock)} from the current stock.`); return; } setBusy(true); setError(""); try { await auth.api(`/products/variants/${active.id}/stock-adjustments`, { method: "POST", body: JSON.stringify({ reason: mode === "RECOUNT" ? "RECOUNT" : reason, mode: mode === "RECOUNT" ? "SET" : "DELTA", value: mode === "DEDUCT" ? -qty : qty, note: note.trim() || null }) }); await reload(); setHistory(await auth.api<Adjustment[]>(`/products/variants/${active.id}/stock-adjustments`)); close(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  if (!active) return <Text style={s.muted}>No variants available.</Text>;
  return <View style={s.sections}>
    <View style={s.stockOverview}>
      {/* Temporarily hidden: stock variant selector. Keep selection logic intact.
      {product.variants.length > 1 && <><Text style={s.stockOverviewLabel}>SELECT VARIANT</Text><View style={s.priceVariantChips}>{product.variants.map(item => <Pressable key={item.id} onPress={() => setVariantId(item.id)} style={[s.priceVariantChip, active.id === item.id && s.priceVariantChipActive]}><Text style={[s.chipText, active.id === item.id && s.activeChipText]}>{variantName(item)}</Text></Pressable>)}</View></>}
      */}
      <View style={s.stockOverviewRow}><Text style={s.stockOverviewLabel}>CURRENT STOCK</Text><Text style={[s.currentStock, currentStock <= 0 && s.negative]}>{currentStock}</Text></View>{currentStock <= 0 && <Text style={s.outOfStock}>Out of stock — add more stock</Text>}</View>
    <View style={s.stockActions}><Pressable onPress={() => open("ADD")} style={[s.stockAction, s.addAction]}><Text style={s.addActionText}>+ Add Stock</Text></Pressable><Pressable onPress={() => open("DEDUCT")} style={[s.stockAction, s.deductAction]}><Text style={s.deductActionText}>− Deduct Stock</Text></Pressable><Pressable onPress={() => open("RECOUNT")} style={[s.stockAction, s.recountAction]}><Text style={s.recountActionText}>Recount</Text></Pressable></View>
    <View><Text style={s.historyTitle}>ADJUSTMENT HISTORY</Text>{history.length ? <View style={s.offerList}>{history.map(item => <View key={item.id} style={s.historyRow}><View style={s.grow}><Text style={s.variantName}>{reasonLabel[item.reason as StockReason] ?? "Other"}</Text>{item.note && <Text style={s.smallMuted}>{item.note}</Text>}<Text style={s.smallMuted}>{item.userName} · {new Date(item.createdAt).toLocaleString("en-GB", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" })}</Text></View><Text style={[s.adjustQty, item.qty < 0 && s.negative]}>{item.qty >= 0 ? "+" : ""}{item.qty}</Text></View>)}</View> : <Text style={s.empty}>No adjustments recorded yet.</Text>}</View>
    <PriceSheet visible={mode !== null} title={mode === "ADD" ? "Add Stock" : mode === "DEDUCT" ? "Deduct Stock" : "Recount Stock"} close={close}>
      {(mode === "ADD" || mode === "DEDUCT") && <View style={s.stockProductSummary}>
        <View style={s.stockProductImage}>{media(active.imageUrl || product.imageUrl) ? <Image source={{ uri: media(active.imageUrl || product.imageUrl)! }} resizeMode="contain" style={s.heroImage} /> : <Ionicons name="cube-outline" size={36} color={colors.muted} />}</View>
        <View style={s.grow}><Label text="Product Name" /><NativeText style={s.sectionTitle}>{product.name}</NativeText></View>
      </View>}
      <Label text={mode === "RECOUNT" ? "HOW MANY IN STOCK?" : "HOW MANY?"} />
      <View style={s.quantityRow}><Pressable onPress={() => step(-1)} style={s.quantityButton}><Text style={s.quantityButtonText}>−</Text></Pressable><TextInput value={value} onChangeText={setValue} keyboardType="decimal-pad" selectTextOnFocus style={s.quantityInput} /><Pressable disabled={mode === "DEDUCT" && entered >= currentStock} onPress={() => step(1)} style={[s.quantityButton, mode === "DEDUCT" && entered >= currentStock && s.disabled]}><Text style={s.quantityButtonText}>+</Text></Pressable></View>
      <Text style={s.projected}>New stock will be: <Text style={s.projectedStrong}>{projected}</Text> <Text style={s.smallMuted}>(Current Stock: {currentStock})</Text></Text>
      {mode !== "RECOUNT" && <><Label text="REASON" /><View style={s.reasonChoices}>{(mode ? reasons[mode] : []).map(item => <Pressable key={item} onPress={() => setReason(item)} style={[s.reasonChoice, reason === item && s.reasonChoiceActive]}><Text style={[s.reasonChoiceText, reason === item && s.reasonChoiceActiveText]}>{reasonLabel[item]}</Text></Pressable>)}</View></>}
      <TextInput value={note} onChangeText={setNote} multiline placeholder="Note (optional)" placeholderTextColor={colors.muted} style={[s.input, s.stockNote]} />
      {!!error && <Text style={s.error}>{error}</Text>}
      <Pressable disabled={busy} onPress={() => void submit()} style={[s.primary, busy && s.disabled]}>{busy ? <ActivityIndicator color={colors.white} /> : <Text style={s.primaryText}>Save Adjustment</Text>}</Pressable>
    </PriceSheet>
  </View>;
}
function Marketplace({ product, auth, reload }: { product: Product; auth: ReturnType<typeof useAuth>; reload: () => Promise<void> }) {
  type Row = { label: string; value: string; placeholder?: string };
  const { lang } = useLanguage();
  const sections: { key: MarketplaceSection; title: string }[] = [{ key: "STYLE", title: "Style" }, { key: "FEATURES_SPECS", title: "Features & Specs" }, { key: "ITEM_DETAILS", title: "Item Details" }];
  const initialRows = () => { const grouped: Record<MarketplaceSection, Row[]> = { STYLE: [], FEATURES_SPECS: [], ITEM_DETAILS: [] }; [...(product.marketplaceDetails ?? [])].sort((a, b) => a.sortOrder - b.sortOrder).forEach(item => grouped[item.section].push({ label: item.label, value: item.value })); return grouped; };
  const [youtubeUrl, setYoutubeUrl] = useState(product.youtubeUrl ?? ""); const [marketplacePrice, setMarketplacePrice] = useState(product.marketplacePrice == null ? "" : String(product.marketplacePrice)); const [rows, setRows] = useState<Record<MarketplaceSection, Row[]>>(initialRows); const [templates, setTemplates] = useState<MarketplaceTemplate[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [saved, setSaved] = useState(false);
  useEffect(() => { auth.api<MarketplaceTemplate[]>(`/products/marketplace-detail-templates?categoryId=${encodeURIComponent(product.categoryId)}`).then(items => { setTemplates(items); if (!(product.marketplaceDetails ?? []).length) setRows(current => { if (Object.values(current).some(items => items.length)) return current; const next: Record<MarketplaceSection, Row[]> = { STYLE: [], FEATURES_SPECS: [], ITEM_DETAILS: [] }; [...items].sort((a, b) => a.sortOrder - b.sortOrder).forEach(item => next[item.section].push({ label: item.label, value: "", placeholder: item.valuePlaceholder ?? undefined })); return next; }); }).catch(() => setTemplates([])); }, [product.categoryId]);
  const updateRow = (section: MarketplaceSection, index: number, field: "label" | "value", value: string) => setRows(current => ({ ...current, [section]: current[section].map((row, i) => i === index ? { ...row, [field]: value } : row) }));
  const addRow = (section: MarketplaceSection, label = "", placeholder?: string | null) => setRows(current => ({ ...current, [section]: [...current[section], { label, value: "", placeholder: placeholder ?? undefined }] }));
  const removeRow = (section: MarketplaceSection, index: number) => setRows(current => ({ ...current, [section]: current[section].filter((_, i) => i !== index) }));
  const save = async () => { const price = marketplacePrice.trim() ? Number(marketplacePrice) : null; if (price != null && (!Number.isFinite(price) || price < 0)) { setError("Enter a valid marketplace price."); return; } const details: { section: MarketplaceSection; label: string; value: string; sortOrder: number }[] = []; sections.forEach(section => rows[section.key].forEach((row, sortOrder) => { if (row.label.trim() && row.value.trim()) details.push({ section: section.key, label: row.label.trim(), value: row.value.trim(), sortOrder }); })); setBusy(true); setError(""); setSaved(false); try { await auth.api(`/products/${product.id}/marketplace-details`, { method: "PUT", body: JSON.stringify({ youtubeUrl: youtubeUrl.trim() || null, details, marketplacePrice: price }) }); await reload(); setSaved(true); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <View style={s.marketplaceSections}><Text style={s.marketplaceIntro}>Optional details shown on the public product page — none of this is required.</Text>{!product.imageUrl && <View style={s.marketWarning}><Text style={s.marketWarningText}>⚠️ Add a product photo before displaying this product in the marketplace.</Text></View>}<View style={s.card}><Label text={lang === "bn" ? "মার্কেটপ্লেসের দাম (ঐচ্ছিক)" : "MARKETPLACE PRICE (OPTIONAL)"} /><TextInput value={marketplacePrice} onChangeText={value => { setMarketplacePrice(value); setSaved(false); }} keyboardType="decimal-pad" placeholder={lang === "bn" ? "দাম লিখুন" : String(product.sellingPrice)} placeholderTextColor={colors.muted} style={s.input} /><Text style={s.smallMuted}>{marketplacePrice.trim() ? "This price will be shown only on the marketplace." : `Leave blank to show your normal Selling Price on the marketplace too (${money(product.sellingPrice)})`}</Text></View><View><Label text={lang === "bn" ? "ইউটিউব ভিডিওর লিংক (ঐচ্ছিক)" : "YOUTUBE VIDEO URL (OPTIONAL)"} /><TextInput value={youtubeUrl} onChangeText={value => { setYoutubeUrl(value); setSaved(false); }} autoCapitalize="none" keyboardType="url" placeholder={lang === "bn" ? "ইউটিউব ভিডিওর লিংক দিন" : "https://www.youtube.com/watch?v=…"} placeholderTextColor={colors.muted} style={s.input} /></View>{sections.map(section => <View key={section.key} style={s.card}><Text style={s.sectionTitle}>{section.title}</Text>{templates.some(item => item.section === section.key) && <><Text style={s.smallMuted}>Pick from template</Text><View style={s.templateChips}>{templates.filter(item => item.section === section.key).map(template => { const added = rows[section.key].some(row => row.label === template.label); return <Pressable key={template.label} disabled={added} onPress={() => addRow(section.key, template.label, template.valuePlaceholder)} style={[s.templateChip, added && s.templateChipAdded]}><Text style={[s.templateChipText, added && s.templateChipAddedText]}>{added ? "✓ " : "+ "}{template.label}</Text></Pressable>; })}</View></>}{rows[section.key].map((row, index) => <View key={index} style={s.marketRow}><TextInput value={row.label} onChangeText={value => updateRow(section.key, index, "label", value)} placeholder="Label" placeholderTextColor={colors.muted} style={[s.input, s.grow]} /><TextInput value={row.value} onChangeText={value => updateRow(section.key, index, "value", value)} placeholder={row.placeholder || "Value"} placeholderTextColor={colors.muted} style={[s.input, s.grow]} /><Pressable accessibilityLabel="Remove row" onPress={() => removeRow(section.key, index)} hitSlop={7}><Ionicons name="close" size={20} color={colors.muted} /></Pressable></View>)}<Pressable onPress={() => addRow(section.key)} style={s.addMarketRow}><Ionicons name="add" size={16} color={colors.primaryDark} /><Text style={s.actionText}>Add row</Text></Pressable></View>)}{!!error && <Text style={s.errorBox}>{error}</Text>}{saved && <Text style={s.savedMessage}>Marketplace details saved.</Text>}<Pressable disabled={busy} onPress={() => void save()} style={[s.primary, busy && s.disabled]}>{busy ? <ActivityIndicator color={colors.white} /> : <Text style={s.primaryText}>Save Marketplace Details</Text>}</Pressable></View>;
}

function EditModal({ visible, product, saving, close, save }: { visible: boolean; product: Product; saving: boolean; close: () => void; save: (payload: object) => Promise<void> }) {
  const { lang } = useLanguage();
  return <Modal visible={visible} transparent animationType="fade" onRequestClose={() => { if (!saving) close(); }}>
    <View style={s.overlay}><SafeAreaView style={s.editModal}>
      <View style={s.editModalHeader}><View style={s.grow}><Text style={s.modalTitle}>{lang === "bn" ? "পণ্য সম্পাদনা" : "Edit product"}</Text><NativeText numberOfLines={1} style={s.editModalSubtitle}>{product.name} · {product.sku}</NativeText></View><Pressable accessibilityRole="button" accessibilityLabel={lang === "bn" ? "বন্ধ করুন" : "Close edit product"} disabled={saving} onPress={close} style={[s.editModalClose,saving && s.disabled]}><Ionicons name="close" size={22} color={colors.heading}/></Pressable></View>
      {visible && <NewProductForm key={product.id} initialProduct={product} onUpdate={fields => save({...product,...fields})} contentStyle={{padding:20,paddingBottom:24}}/>}
    </SafeAreaView></View>
  </Modal>;
}

